code_sketch:
module.exports = function (file, api) {
  const j = api.jscodeshift;
  return j(file.source)
    .find(j.BinaryExpression, { operator: "+" })
    .filter((p) => j.Literal.check(p.node.right) && p.node.right.value === 0)
    .replaceWith((p) => p.node.left)     // x + 0 -> x
    .toSource();
};

