module.exports = {
  meta: { fixable: "code" },
  create(context) {
    return {
      "BinaryExpression[operator='+'] > Literal.right[value=0]"(node) {
        context.report({
          node, message: "x + 0 is x",
          fix: (f) => f.replaceText(node, context.sourceCode.getText(node.left)),
        });
      },
    };
  },
};
